use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,path::Path,process::Command};
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn main(){let r=Path::new("/home/ubuntu/src/zopro-perf-work/g2-queue-scan-count175");let z=Path::new("/home/ubuntu/src/zk-tools/zopro");let d=z.join("docs/benchmarks/2026-10-30-g2-queue-scan-count175");let s=z.join("docs/benchmarks/2026-10-29-current-cpu-summary");let pins=read(r.join("pins-fixed.json"));for(p,h)in pins.as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}let sources=read(s.join("source-hashes.json"));for(p,h)in sources.as_object().unwrap(){assert_eq!(hash(z.join(p)),h.as_str().unwrap());}let old=Command::new("git").args(["show","6bd0900872:zopro/docs/benchmarks/2026-10-29-current-cpu-summary/data.json"]).output().unwrap();assert!(old.status.success());let old:Value=serde_json::from_slice(&old.stdout).unwrap();let now=read(s.join("data.json"));assert_eq!(old["rows"],now["rows"]);assert_eq!(now["historical_distinct_Gnark_ledger"],23971);let a=read(d.join("artifacts/analysis.json"));assert_eq!(a["necessary_opportunity_gate"],true);assert_eq!(a["rows"],now["latest_G2_queue_scan_count_model"]["rows"]);let mut links=0;for base in[&d,&s]{let md=fs::read_to_string(base.join("README.md")).unwrap();for tail in md.split("](").skip(1){let p=tail.split(')').next().unwrap();assert!(base.join(p).is_file(),"missing {p}");links+=1;}}
 assert_eq!(read(r.join("runs/result.json"))["steps"].as_array().unwrap().len(),4);let tests=fs::read_to_string(r.join("runs/test-model/stdout.log")).unwrap();assert!(tests.contains("2 passed; 0 failed; 0 ignored; 0 measured; 0 filtered out"));println!("{}",json!({"original_source_library_input_pins":pins.as_object().unwrap().len(),"summary_source_pins":sources.as_object().unwrap().len(),"production_source_hashes_included":175,"all_9_accepted_local_AWS_rows_unchanged":true,"all_8_CPU_Metal_rows_unchanged":true,"links":links,"proof_ledger":23971,"performance_claim":false,"production_changed":false}));}
